import{c as t,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"InitDetermineComputeWorkspace","description":"","frontmatter":{},"headers":[{"level":1,"title":"InitDetermineComputeWorkspace","slug":"initdeterminecomputeworkspace"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/同步控制/核间同步/InitDetermineComputeWorkspace.md","filePath":"api/SIMD-API/基础API/同步控制/核间同步/InitDetermineComputeWorkspace.md"}'),l={name:"api/SIMD-API/基础API/同步控制/核间同步/InitDetermineComputeWorkspace.md"};function p(o,a,i,r,c,d){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="initdeterminecomputeworkspace" tabindex="-1">InitDetermineComputeWorkspace <a class="header-anchor" href="#initdeterminecomputeworkspace" aria-label="Permalink to &quot;InitDetermineComputeWorkspace&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>初始化GM共享内存的值，完成初始化后才可以调用<a href="./WaitPreBlock.html">WaitPreBlock</a>和<a href="./NotifyNextBlock.html">NotifyNextBlock</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void InitDetermineComputeWorkspace(GlobalTensor&lt;int32_t&gt;&amp; gmWorkspace, LocalTensor&lt;int32_t&gt;&amp; ubWorkspace)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>gmWorkspace</td><td>输入</td><td>临时空间，初始化核间同步的共享内存，类型为GlobalTensor。</td></tr><tr><td>ubWorkspace</td><td>输入</td><td>临时空间，用于操作gmWorkspace，类型为LocalTensor。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>gmWorkspace申请的空间最少要求为：blockNum * 32Bytes；ubWorkspace申请的空间最少要求为：blockNum * 32 + 32Bytes；其中blockNum为调用的核数，可调用<a href="./../../系统变量访问/GetBlockNum.html">GetBlockNum</a>获取。</li><li>使用该接口进行多核控制时，算子调用时指定的逻辑numBlocks必须保证不大于实际运行该算子的AI处理器核数，否则框架进行多轮调度时会插入异常同步，导致Kernel“卡死”现象。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>如下示例模拟8个核进行数据处理，使用确定性计算接口保证核间运行顺序，进行原子累加。如需运行，请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/06_sync_control/sequential_block_sync" target="_blank" rel="noreferrer">核间顺序同步样例</a>实现完整的代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// m_gmWorkspace为初始化核间同步的共享内存，类型为GlobalTensor；ubWorkspace为操作m_gmWorkspace的临时空间，类型为LocalTensor</span></span>
<span class="line"><span>int64_t m_tileCount = 256 * sizeof(int32_t); // 参与计算的元素总数所占的空间，单位为bytes</span></span>
<span class="line"><span>// 初始化GM共享内存的值</span></span>
<span class="line"><span>AscendC::InitDetermineComputeWorkspace(m_gmWorkspace, ubWorkspace);</span></span>
<span class="line"><span>// copy in</span></span>
<span class="line"><span>// srcLocal为int32_t类型的LocalTensor，m_srcGlobal为int32_t的GlobalTensor</span></span>
<span class="line"><span>AscendC::DataCopy(srcLocal, m_srcGlobal[m_tileCount], m_tileCount);</span></span>
<span class="line"><span>// copy out</span></span>
<span class="line"><span>// 调用WaitPreBlock读GM地址中的值，确认是否需要继续等待</span></span>
<span class="line"><span>AscendC::WaitPreBlock(m_gmWorkspace, ubWorkspace);</span></span>
<span class="line"><span>// 开启原子累加</span></span>
<span class="line"><span>AscendC::SetAtomicAdd&lt;int32_t&gt;();</span></span>
<span class="line"><span>// m_dstGlobal为int32_t的GlobalTensor</span></span>
<span class="line"><span>AscendC::DataCopy(m_dstGlobal[m_tileCount], srcLocal, m_tileCount);</span></span>
<span class="line"><span>AscendC::DisableDmaAtomic();</span></span>
<span class="line"><span>// 调用NotifyNextBlock写GM地址，通知下一个核当前核的操作已完成，下一个核可以进行操作</span></span>
<span class="line"><span>AscendC::NotifyNextBlock(m_gmWorkspace, ubWorkspace);</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//每个核的输入数据为: </span></span>
<span class="line"><span>[1,1,1,1,1,...,1] // 256个1</span></span>
<span class="line"><span>//最终输出数据:</span></span>
<span class="line"><span>[8,8,8,8,8,...,8] // 256个8</span></span></code></pre></div>`,18)])])}const u=t(l,[["render",p]]);export{h as __pageData,u as default};
